using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor.SceneManagement;

public static class NemoDesignVerifier
{
    [Serializable]public class Row{public int seed,sprites,fixedNativeTrees,groundMeshes,boundaryAddedSprites,boundaryAddedTrees;public string designDigest;public bool success,visualFrozen,onlyFixedForestReferences,artImageUnchanged;public string[] errors;}
    [Serializable]public class Report{public bool success,cachedReadMaskEquivalent,cachedReadDesignEquivalent;public Row[] seeds;public string scope;}
    public static void Inspect(){string seed0Mask=null,seed0Digest=null;var rows=new List<Row>();foreach(int seed in new[]{0,17,42,99,20261011}){var row=new Row{seed=seed};var errors=new List<string>();try{EditorSceneManager.OpenScene(seed==0?NemoRiverVerifier.ScenePath:"Assets/NemoBlocks/Scenes/RiverSeeds/NemoRiverSeed"+seed+".unity");var walk=UnityEngine.Object.FindAnyObjectByType<NemoWalk>();var map=walk.Map;if(seed==0){seed0Mask=map.Boundary.WalkRegion.SavedGroundMask;seed0Digest=map.Design.VisualDigest;}row.sprites=map.Design.SpriteCount;row.fixedNativeTrees=map.Design.Forest.Length;row.groundMeshes=map.Design.Ground.Length;row.designDigest=map.Design.VisualDigest;row.visualFrozen=map.Design.NoVisualMutation&&row.designDigest==NemoBlockDesignFreeze.Digest(map);row.boundaryAddedSprites=map.Boundary.GetComponentsInChildren<SpriteRenderer>(true).Length;row.boundaryAddedTrees=map.Boundary.AddedTreeFeet.Length;row.onlyFixedForestReferences=map.Boundary.Supports.Length==map.Design.Forest.Length&&map.Boundary.Supports.SelectMany(s=>s.visuals).All(s=>map.Design.Forest.Any(f=>f.visuals.Contains(s)));
        string before=Path.Combine(NemoBuilder.Evidence,"design-seed-"+seed+"-physical-off.png"),after=Path.Combine(NemoBuilder.Evidence,"design-seed-"+seed+"-physical-on.png");map.Boundary.gameObject.SetActive(false);NemoBuilder.Capture(walk.View,new Vector2(72,54),56,before,1728,1296);map.Boundary.gameObject.SetActive(true);NemoBuilder.Capture(walk.View,new Vector2(72,54),56,after,1728,1296);row.artImageUnchanged=File.ReadAllBytes(before).SequenceEqual(File.ReadAllBytes(after));if(!row.visualFrozen||!row.onlyFixedForestReferences||!row.artImageUnchanged||row.boundaryAddedSprites!=0||row.boundaryAddedTrees!=0||row.groundMeshes==0)errors.Add("Physical boundary changed or furnished the fixed block level design");
    }catch(Exception e){errors.Add(e.ToString());Debug.LogException(e);}row.errors=errors.ToArray();row.success=errors.Count==0;rows.Add(row);Debug.Log("NEMO_DESIGN_FIRST "+seed+" "+row.success);}var rebuilt=NemoBuilder.Create(0,true);bool maskSame=seed0Mask==rebuilt.Map.Boundary.WalkRegion.SavedGroundMask,designSame=seed0Digest==rebuilt.Map.Design.VisualDigest;File.WriteAllText(Path.Combine(NemoBuilder.Evidence,"design-first-verification.json"),JsonUtility.ToJson(new Report{success=rows.Count==5&&rows.All(s=>s.success)&&maskSame&&designSame,cachedReadMaskEquivalent=maskSame,cachedReadDesignEquivalent=designSame,seeds=rows.ToArray(),scope="Block level design (native forest, rendered soil/working-yard meshes and facilities) captured before access/collision. No physical-boundary Sprite or tree additions; existing visual/mesh digest preserved. Forest support references all belong to that snapshot. Actual full GPU images identical with physical boundary disabled/enabled. G/H separately checked by walking verifier."},true));EditorSceneManager.OpenScene(NemoRiverVerifier.ScenePath);}
}
